                                <text style="background:#fee2e2;color:#991b1b;padding:4rpx 12rpx;border-radius:8rpx;">不够+磨标 ×{{ rule.moqUnmetOemCoeff }}</text>
                                <text style="background:#fef3c7;color:#92400e;padding:4rpx 12rpx;border-radius:8rpx;">不够+原装 ×{{ rule.moqUnmetOriginalCoeff }}</text>
