<script>
import navigationBar from '@/components/navigation-bar/navigation-bar';
import { priceApi, storage } from '@/utils/cloud-api';

export default {
    components: {
        navigationBar
    },
    data() {
        return {
            fileName: '',
            fileSize: '',
            fileData: null,
            previewData: [],
            integratedPreview: null,
            coefficientRules: [],
            failedRows: [],
            stats: {
                total: 0,
                success: 0,
                failed: 0,
                coeffCount: 0
            },
            isUploading: false,
            currentUser: null,
            sheetNames: [],
            selectedSheet: '',
            needSheetSelection: false,
            importType: 'integrated'
        };
    },
    methods: {
        onLoad() {
            this.checkLogin();
        },
        onShow() {
            this.checkLogin();
            // 检查是否从本地文件选择器返回
            this.checkPickedFile();
        },
        checkLogin() {
            const user = storage.getUser();
            if (!user) {
                uni.redirectTo({
                    url: '/pages/login/login'
                });
                return;
            }
            this.currentUser = user;
        },
        handleLogout() {
            uni.showModal({
                title: '确认退出',
                content: '确定要退出登录吗？',
                success: (res) => {
                    if (res.confirm) {
                        storage.removeUser();
                        uni.redirectTo({
                            url: '/pages/login/login'
                        });
                    }
                }
            });
        },
        chooseFile() {
            uni.showActionSheet({
                itemList: ['从手机本地文件选择', '从微信聊天记录选择'],
                success: (res) => {
                    if (res.tapIndex === 0) {
                        // 从手机本地文件选择（WebView 方式，打开系统原生文件选择器）
                        this.chooseLocalFile();
                    } else if (res.tapIndex === 1) {
                        // 从微信聊天记录选择（原有方式）
                        this.chooseFromChat();
                    }
                }
            });
        },

        /**
         * 从手机本地文件选择 - 使用 WebView + <input type="file">
         * 这会打开手机系统的原生文件选择器，可以访问设备上的所有文件
         */
        chooseLocalFile() {
            uni.navigateTo({
                url: '/pages/file-picker/file-picker',
                fail: (err) => {
                    console.error('打开文件选择器失败:', err);
                    uni.showToast({
                        title: '无法打开文件选择器，请尝试从微信聊天选择',
                        icon: 'none',
                        duration: 3000
                    });
                }
            });
        },

        /**
         * 统一处理已选择的文件（校验 + 解析）
         */
        handleSelectedFile(file) {
            if (file.size > 10 * 1024 * 1024) {
                uni.showToast({ title: '文件大小不能超过10MB', icon: 'none' });
                return;
            }
            this.fileName = file.name;
            this.fileSize = this.formatFileSize(file.size);
            this.fileData = file;
            this.parseFile(file);
        },

        /**
         * 从微信聊天记录选择文件
         */
        chooseFromChat() {
            uni.chooseMessageFile({
                count: 1,
                type: 'file',
                extension: ['.xlsx', '.xls', '.csv'],
                success: (res) => {
                    this.handleSelectedFile(res.tempFiles[0]);
                },
                fail: (err) => {
                    console.error('选择文件失败:', err);
                    uni.showToast({ title: '选择文件失败', icon: 'none' });
                }
            });
        },

        /**
         * 检查是否从本地文件选择器返回了文件数据
         */
        checkPickedFile() {
            const app = getApp();
            const file = app.globalData && app.globalData.pickedFile;
            if (!file || !file.path) return;

            // 清除全局数据，防止重复处理
            delete app.globalData.pickedFile;
            console.log('检测到从本地文件选择器返回的文件:', file.name);
            this.handleSelectedFile(file);
        },

        formatFileSize(bytes) {
            if (bytes < 1024) return bytes + ' B';
            if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
            return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
        },

        async parseFile(file) {
            uni.showLoading({
                title: '正在解析文件...',
                mask: true
            });

            try {
                const result = await priceApi.importFile(file.path, file.name, this.selectedSheet, this.importType);
                this.handleParseResult(result);
            } catch (error) {
                console.error('解析文件失败:', error);
                uni.showToast({
                    title: '解析失败，请重试',
                    icon: 'none'
                });
            } finally {
                uni.hideLoading();
            }
        },

        handleParseResult(result) {
            console.log('[handleParseResult] 完整结果: ' + JSON.stringify(result));

            if (result.success) {
                const importType = result.data.importType || this.importType;
                
                if (importType === 'integrated') {
                    this.integratedPreview = result.data.previewData || {};
                    this.coefficientRules = result.data.coefficientRules || [];
                    this.failedRows = result.data.failedRows || [];
                    this.stats.total = result.data.rowsCount || 0;
                    this.stats.success = result.data.successCount || 0;
                    this.stats.failed = this.failedRows.length;
                    this.stats.coeffCount = this.coefficientRules.length;
                    this.previewData = [];
                } else {
                    this.previewData = result.data.previewData || [];
                    this.coefficientRules = result.data.coefficientRules || [];
                    this.failedRows = result.data.failedRows || [];
                    this.stats.total = result.data.rowsCount || 0;
                    this.stats.success = result.data.successCount || 0;
                    this.stats.failed = this.failedRows.length;
                    this.stats.coeffCount = this.coefficientRules.length;
                    this.integratedPreview = null;
                }

                if (result.data.sheetNames && result.data.sheetNames.length > 1) {
                    this.sheetNames = result.data.sheetNames;
                    this.selectedSheet = result.data.selectedSheet || '';
                } else {
                    this.sheetNames = [];
                    this.selectedSheet = '';
                }

                this.needSheetSelection = false;

                console.log('[handleParseResult] 解析成功: total=' + this.stats.total +
                    ', success=' + this.stats.success + ', failed=' + this.stats.failed +
                    ', previewData=' + this.previewData.length + '条' +
                    ', coefficientRules=' + this.coefficientRules.length + '条');

                if (this.failedRows.length > 0) {
                    console.log('[handleParseResult] 失败行详情: ' + JSON.stringify(this.failedRows.slice(0, 10)));
                    uni.showToast({
                        title: '解析完成，' + this.failedRows.length + '条数据有误',
                        icon: 'none',
                        duration: 3000
                    });
                } else {
                    uni.showToast({
                        title: '解析成功',
                        icon: 'success'
                    });
                }
            } else {
                console.error('[handleParseResult] 解析失败: ' + (result.message || '无错误信息'));

                const msg = result.message || '解析失败';
                if (msg.includes('未指定工作表') && msg.includes('可用工作表')) {
                    const match = msg.match(/可用工作表: ([^，。]+)/);
                    if (match && match[1]) {
                        this.sheetNames = match[1].split(/,|，/).map(s => s.trim()).filter(s => s);
                        this.needSheetSelection = true;
                        this.previewData = [];
                        this.failedRows = [];
                        this.stats = { total: 0, success: 0, failed: 0, coeffCount: 0 };

                        uni.showToast({
                            title: '请选择工作表',
                            icon: 'none',
                            duration: 3000
                        });
                        return;
                    }
                }

                uni.showToast({
                    title: msg,
                    icon: 'none',
                    duration: 4000
                });
            }
        },

        selectSheet(sheet) {
            this.selectedSheet = sheet;
        },

        async downloadTemplate() {
            uni.showLoading({ title: '正在下载...', mask: true });

            try {
                let result;
                if (this.importType === 'material') {
                    result = await priceApi.getMaterialLibraryTemplateUrl();
                } else {
                    result = await priceApi.getTemplateUrl();
                }
                if (!result || !result.downloadUrl) {
                    uni.hideLoading();
                    uni.showToast({ title: '模板暂不可用', icon: 'none' });
                    return;
                }

                const downloadRes = await new Promise((resolve, reject) => {
                    uni.downloadFile({ url: result.downloadUrl, success: resolve, fail: reject });
                });

                uni.hideLoading();

                if (downloadRes.statusCode !== 200) {
                    uni.showToast({ title: '下载失败(' + downloadRes.statusCode + ')', icon: 'none' });
                    return;
                }

                // 先弹窗提示，用户确认后再打开文件预览
                uni.showModal({
                    title: '下载完成',
                    content: '打开文件后，点击右上角 ··· 菜单\n选择「保存」或「转发」\n即可保存到手机或发送给好友。',
                    confirmText: '打开文件',
                    cancelText: '稍后再说',
                    success: (modalRes) => {
                        if (modalRes.confirm) {
                            uni.openDocument({
                                filePath: downloadRes.tempFilePath,
                                fileType: 'xlsx',
                                showMenu: true,
                                fail: (err) => {
                                    console.error('打开失败:', err);
                                    // 兜底：保存到沙盒再试
                                    uni.saveFile({
                                        tempFilePath: downloadRes.tempFilePath,
                                        success: (saveRes) => {
                                            uni.openDocument({
                                                filePath: saveRes.savedFilePath,
                                                fileType: 'xlsx',
                                                showMenu: true,
                                                fail: () => uni.showToast({ title: '请更新微信版本', icon: 'none' })
                                            });
                                        },
                                        fail: () => uni.showToast({ title: '保存失败，请重试', icon: 'none' })
                                    });
                                }
                            });
                        }
                    }
                });
            } catch (error) {
                uni.hideLoading();
                console.error('下载模板失败:', error);
                uni.showToast({ title: '下载失败，请重试', icon: 'none' });
            }
        },

        confirmImport() {
            const hasData = this.previewData && this.previewData.length > 0;
            const hasIntegratedData = this.integratedPreview && 
                (this.integratedPreview.series?.length > 0 || 
                 this.integratedPreview.models?.length > 0 || 
                 this.integratedPreview.prices?.length > 0 || 
                 this.integratedPreview.materials?.length > 0 ||
                 this.integratedPreview.materialDiffs?.length > 0);

            if (!hasData && !hasIntegratedData) {
                uni.showToast({
                    title: '没有可导入的数据',
                    icon: 'none'
                });
                return;
            }

            let content = '';
            if (this.importType === 'integrated' && this.integratedPreview) {
                content = `即将导入整合数据：\n` +
                    (this.integratedPreview.series?.length ? `· 产品系列: ${this.integratedPreview.series.length}条\n` : '') +
                    (this.integratedPreview.models?.length ? `· 阀门型号: ${this.integratedPreview.models.length}条\n` : '') +
                    (this.integratedPreview.prices?.length ? `· 价格数据: ${this.integratedPreview.prices.length}条\n` : '') +
                    (this.integratedPreview.materials?.length ? `· 材质配置: ${this.integratedPreview.materials.length}条\n` : '') +
                    (this.integratedPreview.materialDiffs?.length ? `· 材质价差: ${this.integratedPreview.materialDiffs.length}条\n` : '') +
                    (this.coefficientRules.length ? `· 报价系数: ${this.coefficientRules.length}条` : '');
            } else {
                const typeName = this.importType === 'price' ? '价格' : 
                    this.importType === 'material_lib' ? '材质库' : '材质配置';
                content = `即将导入 ${this.previewData.length} 条${typeName}数据，确认继续？`;
            }

            uni.showModal({
                title: '确认导入',
                content: content,
                confirmText: '确认导入',
                cancelText: '取消',
                success: (res) => {
                    if (res.confirm) {
                        this.doImport();
                    }
                }
            });
        },

        async doImport() {
            uni.showLoading({
                title: '正在导入数据...',
                mask: true
            });

            console.log('[doImport] 开始导入, 类型: ' + this.importType);

            try {
                let result;
                if (this.importType === 'integrated') {
                    result = await priceApi.confirmImport(this.integratedPreview, this.coefficientRules, 'integrated');
                } else {
                    result = await priceApi.confirmImport(this.previewData, this.coefficientRules, this.importType);
                }
                console.log('[doImport] 导入结果: ' + JSON.stringify(result));

                if (!result) {
                    console.error('[doImport] 云函数返回空结果');
                    uni.showToast({ title: '导入失败：服务器无响应', icon: 'none' });
                } else if (!result.success && result.message) {
                    console.error('[doImport] 导入失败: ' + result.message);
                    uni.showModal({
                        title: '导入失败',
                        content: result.message,
                        showCancel: false,
                        confirmText: '确定'
                    });
                } else if (result.successCount !== undefined) {
                    uni.showModal({
                        title: '导入完成',
                        content: '成功导入 ' + result.successCount + ' 条数据，失败 ' + (result.failedCount || 0) + ' 条',
                        showCancel: false,
                        confirmText: '确定',
                        success: () => {
                            this.clearFile();
                        }
                    });
                } else if (result.data && this.importType === 'integrated') {
                    const d = result.data;
                    const msg = `整合导入完成：\n` +
                        `· 系列: 创建${d.series.created} 更新${d.series.updated} 失败${d.series.failed}\n` +
                        `· 型号: 创建${d.models.created} 更新${d.models.updated} 失败${d.models.failed}\n` +
                        `· 价格: 创建${d.prices.created} 更新${d.prices.updated} 失败${d.prices.failed}\n` +
                        `· 材质: 创建${d.materials.created} 更新${d.materials.updated} 失败${d.materials.failed}\n` +
                        `· 系数: 创建${d.coefficients.created} 更新${d.coefficients.updated} 失败${d.coefficients.failed}`;
                    uni.showModal({
                        title: '导入完成',
                        content: msg,
                        showCancel: false,
                        confirmText: '确定',
                        success: () => {
                            this.clearFile();
                        }
                    });
                } else {
                    console.error('[doImport] 未知返回格式: ' + JSON.stringify(result));
                    uni.showToast({ title: '导入失败，返回数据异常', icon: 'none' });
                }
            } catch (error) {
                console.error('[doImport] 异常: ' + JSON.stringify(error));
                uni.showToast({ title: '导入失败: ' + (error.message || '请重试'), icon: 'none', duration: 4000 });
            } finally {
                uni.hideLoading();
            }
        },

        reparseFile() {
            if (this.fileData) {
                this.parseFile(this.fileData);
            }
        },

        clearFile() {
            this.fileName = '';
            this.fileSize = '';
            this.fileData = null;
            this.previewData = [];
            this.coefficientRules = [];
            this.failedRows = [];
            this.stats = {
                total: 0,
                success: 0,
                failed: 0,
                coeffCount: 0
            };
            this.sheetNames = [];
            this.selectedSheet = '';
            this.needSheetSelection = false;
        }
    }
};
</script>

